export function completedFactsPatch(group){const f=completedFragranceFacts[group];return f?{...structuredClone(f),...processNotes(f)}:null;}
// Only exact prior seed notes are eligible. Owner edits and deleted listings stay intact.
export function completeSeedFragrance(p){
 const facts=completedFactsPatch(p.group);if(!facts||p.factsRevision>=2)return p;
 const prior=previousSeedFacts[p.group]?.find(q=>q.notes===p.notes&&JSON.stringify(q.notePyramid)===JSON.stringify(p.notePyramid||null)&&JSON.stringify(q.signatureNotes)===JSON.stringify(p.signatureNotes||null));
 if(!prior)return p;
 const result={...p,...facts};if(!facts.notePyramid)delete result.notePyramid;if(!facts.signatureNotes)delete result.signatureNotes;
 if(p.description!==prior.description)result.description=p.description;return result;
}
